use filmcraft_project::{Project,ItemId};use filmcraft_media::{SharedSource,still::StillSource,generators::{Generator,GeneratorSource}};use filmcraft_time::{Tick,FrameRate};use filmcraft_render::{render_sequence,RenderOptions};use filmcraft_color::{ColorSpace,HdrMetadata};use serde_json::{Value,json};use std::sync::Arc;
fn main(){let fixture:Value=serde_json::from_slice(&std::fs::read(std::env::args().nth(1).unwrap()).unwrap()).unwrap();let base=fixture["cases"].as_array().unwrap().iter().find(|c|c["scale"]==1.&&c["effect"]=="invert"&&c["mask_mode"]=="Add"&&c["profile"]==1).unwrap();let mut cases=vec![];
for kind in ["image","generator"]{for cs in ColorSpace::ALL{for auto in [false,true]{for peak in [None,Some(3999.75f32)]{let mut doc=base["document"].clone();let media=&mut doc["project"]["items"]["1"]["kind"]["Media"];media["interpret"]["color_space"]=json!(cs);media["info"]["video"]["hdr"]=json!(peak.map(|p|HdrMetadata{max_cll:Some(p),mastering_max_nits:Some(5000.),..Default::default()}));let w=media["info"]["video"]["width"].as_u64().unwrap()as u32;let h=media["info"]["video"]["height"].as_u64().unwrap()as u32;
let source:SharedSource=if kind=="image"{let rgba=(0..w*h).flat_map(|i|[((i*37+11)%256)as u8,((i*73+51)%256)as u8,((i*19+83)%256)as u8,[0,1,64,128,255][i as usize%5]]).collect();media["media"]=json!({"File":{"path":"/original/interpret.png"}});Arc::new(StillSource::from_rgba("interpret.png",w,h,rgba,true,0))}else{let generator:Generator=serde_json::from_value(media["media"]["Generator"].clone()).unwrap();Arc::new(GeneratorSource::new(generator,w,h,FrameRate::FPS_24,Tick(5080320000000)))};
doc["project"]["items"]["6"]["kind"]["Sequence"]["settings"]["color"]["auto_tone_map"]=json!(auto);
// Resolve the override through a real subclip, not just direct root media.
doc["project"]["items"]["6"]["kind"]["Sequence"]["video_tracks"][0]["items"][0]["item"]=json!(2);
let p:Project=serde_json::from_value(doc["project"].clone()).unwrap();let provider=|id:ItemId|{let(root,_,_)=p.resolve_media(id)?;(root==ItemId(1)).then(||source.clone())};
for scale in [1f32,0.5,0.25]{let out=render_sequence(&p,ItemId(6),Tick(0),RenderOptions{scale,working_output:true,..Default::default()},&provider);cases.push(json!({"document":doc,"sequence":6,"at":0,"kind":kind,"scale":scale,"sourceWidth":w,"sourceHeight":h,"width":out.w,"height":out.h,"bits":out.px.iter().map(|v|v.to_bits()).collect::<Vec<_>>(),"rgba":out.to_rgba8()}));}
}}}}
println!("{}",json!({"commit":"5231852443363f001c3f6b396dd9b1e6461ae2be","cases":cases}));}
